package cards

import (
	"fmt"
	"html"
)

// PaymentCardBrandCID is embedded as a PNG in both payment and Cashlink emails.
// The mailer includes it whether or not the optional PhoenixMail footer is enabled.
func PaymentCardBrandCID(id string) string {
	return "phoenixmail-nimiq-brand-" + id + "@phoenixmail.local"
}

// Common email-safe layout: table-based with inline styles, a solid pastel
// background fallback for Outlook, and a gradient for clients supporting CSS.
// No scripts, external stylesheets, remote images, or wallet/payment logic.
type paymentCardDesign struct {
	ID, Heading, Network, Amount, BodyHTML, ActionURL, ActionLabel string
	PastelV2                                                       bool
	// Optional. Nimiq cards leave them empty: brand "Nimiq", unit "NIM", the twelve pastel families chosen by the ID.
	// Other assets (USDT) give their own brand line, unit and palette; a card without ActionURL has no button.
	Brand, Unit string
	Colors      [2]string // background, border
	Mid, End    string    // gradient stops after the background
}

func renderPaymentCard(d paymentCardDesign) string {
	colors := PaymentCardColorsFor(d.ID, d.PastelV2)
	if d.Colors[0] != "" {
		colors = d.Colors
	}
	background, border := colors[0], colors[1]
	brandLine, unit, mid, end := d.Brand, d.Unit, d.Mid, d.End
	if brandLine == "" {
		brandLine = "Nimiq"
	}
	if unit == "" {
		unit = "NIM"
	}
	if mid == "" {
		mid, end = "#e2eeff", "#ffe8f4"
	}
	action := ""
	if d.ActionURL != "" {
		action = fmt.Sprintf(`<a href="%s" style="display:inline-block;text-decoration:none;margin:12px auto 4px;padding:13px 17px;border-radius:12px;background:#8170ed;color:#ffffff;font-weight:bold;font-size:14px">%s</a>`, html.EscapeString(d.ActionURL), html.EscapeString(d.ActionLabel))
	}
	brand := "cid:" + PaymentCardBrandCID(d.ID)
	// A small label next to the brand (only the protected card has one); no network name is ever shown.
	chip := ""
	if d.Network != "" {
		chip = fmt.Sprintf(`<span style="display:inline-block;padding:7px 9px;border:1px solid %s;border-radius:22px;background:#ffffff;color:#6752a2;font-size:10px;font-weight:bold">%s</span>`, border, html.EscapeString(d.Network))
	}
	return fmt.Sprintf(`<table role="presentation" align="center" cellpadding="0" cellspacing="0" width="100%%" style="max-width:440px;width:100%%;margin:20px auto;border:1px solid %s;border-radius:26px;background:%s;background-image:linear-gradient(125deg,%s 0%%,%s 56%%,%s 100%%);color:#211e49;font-family:Arial,Helvetica,sans-serif"><tr><td style="padding:22px 22px 20px;text-align:center">
<table role="presentation" cellpadding="0" cellspacing="0" width="100%%" style="border-collapse:collapse;margin-bottom:14px"><tr>
<td valign="middle" style="text-align:left"><img src="%s" width="50" height="50" alt="PhoenixMail" style="display:inline-block;vertical-align:middle;border:0"><span style="font-weight:bold;font-size:21px;vertical-align:middle;color:#25204b">Phoenix<span style="color:#ed9143">Mail</span></span></td>
<td valign="middle" align="right">%s</td>
</tr></table>
<p style="font-size:12px;letter-spacing:1.7px;text-transform:uppercase;color:#7461aa;font-weight:bold;margin:18px 0 12px">%s · %s</p>
<div style="font-size:44px;line-height:1.3;color:#201d47;font-weight:bold;margin:6px 0 12px">%s %s</div>
<table role="presentation" cellpadding="0" cellspacing="0" width="100%%" style="background:#ffffff;border:1px solid #ffffff;border-radius:20px"><tr><td style="padding:19px 14px 21px;text-align:center">
%s
%s
</td></tr></table>
<div style="height:8px;line-height:8px;font-size:8px">&nbsp;</div>
</td></tr></table>`, border, background, background, mid, end, brand, chip,
		html.EscapeString(brandLine), html.EscapeString(d.Heading),
		html.EscapeString(d.Amount), html.EscapeString(unit), d.BodyHTML, action)
}

// CardDesign and RenderCard expose the single card renderer to code that lives next to the Nimiq cards (USDT).
type CardDesign = paymentCardDesign

func RenderCard(d CardDesign) string { return renderPaymentCard(d) }
